"use client";
import { useEffect, type CSSProperties, type ReactNode } from "react";
import Link from "next/link";
import { ScaledCanvas } from "./ScaledCanvas";
import { timing, type Motion } from "@/lib/timing";

// Layer data is generated by tools/migration/capture-product-pages.mjs.
export type Layer = {
  x: number; y: number; w: number; h: number;
  name?: string; href?: string; newTab?: boolean;
  clip?: boolean; opacity?: number; bg?: string; radius?: string; z?: number;
  svg?: string;
  img?: { src: string; fit: string; pos: string; hover?: string };
  video?: { src: string; loop: boolean; fit: string };
  text?: { value: string; color: string; size: number; family: string; weight: number; lineHeight: string; align: string };
  appear?: Motion & { t: string; x: number; y: number; o: number };
  tap?: Motion & { s: number; x: number };
  hover?: Motion & { s: number };
  children?: Layer[];
};
export type ProductPageData = { title: string; height: number; background: string; layers: Layer[] };
/** Replaces (or wraps) the content of layers with a given name, for pages that drive a layer themselves. */
export type Slots = Record<string, (content: ReactNode, layer: Layer) => ReactNode>;

const ARTBOARD = 1200;

const label = (layer: Layer): string | undefined => layer.name ?? layer.children?.map(label).find(Boolean);

export function LayerView({ layer, slots }: { layer: Layer; slots?: Slots }) {
  const { appear, tap, hover, img, video, text } = layer;
  const classes = ["absolute"];
  const style: Record<string, string | number | undefined> = {
    left: layer.x, top: layer.y, width: layer.w, height: layer.h,
    opacity: layer.opacity, background: layer.bg, borderRadius: layer.radius, zIndex: layer.z,
  };
  if (layer.clip) classes.push("overflow-clip");
  if (appear) {
    style["--ax"] = `${appear.x}px`; style["--ay"] = `${appear.y}px`; style["--ao"] = appear.o;
    if (appear.t === "scroll") { classes.push("layer-scroll"); style.transition = `translate ${timing(appear)}`; }
    else style.animation = `layer-appear ${timing(appear)} both`;
  }
  const press = tap ?? hover;
  if (press) {
    classes.push(tap ? "layer-tap" : "layer-hover");
    style["--s"] = press.s; style["--tx"] = `${tap?.x ?? 0}px`;
    style.transition = `scale ${timing(press)}, translate ${timing(press)}`;
  }
  if (img?.hover) classes.push("group");

  let content: ReactNode = layer.children?.map((child, index) => <LayerView key={index} layer={child} slots={slots} />);
  const media = "pointer-events-none block h-full w-full select-none";
  if (layer.svg) content = <img src={layer.svg} alt="" className={media} />;
  if (img) {
    const fit = { objectFit: img.fit, objectPosition: img.pos } as CSSProperties;
    content = <>
      <img src={img.src} alt="" style={fit} className={`${media} ${img.hover ? "transition-opacity duration-200 group-hover:opacity-0" : ""}`} />
      {img.hover && <img src={img.hover} alt="" style={fit} className={`${media} absolute inset-0 opacity-0 transition-opacity duration-200 group-hover:opacity-100`} />}
    </>;
  }
  if (video) content = <video src={video.src} autoPlay muted playsInline loop={video.loop} preload="auto" style={{ objectFit: video.fit } as CSSProperties} className="block h-full w-full" />;
  if (text) content = <span style={{ color: text.color, fontSize: text.size, fontFamily: text.family, fontWeight: text.weight, lineHeight: text.lineHeight, textAlign: text.align } as CSSProperties} className="block whitespace-nowrap">{text.value}</span>;

  if (layer.name && slots?.[layer.name]) content = slots[layer.name](content, layer);

  const props = { className: classes.join(" "), style: style as CSSProperties };
  if (!layer.href) return <div {...props}>{content}</div>;
  const accessible = text ? undefined : label(layer);
  if (layer.newTab || !layer.href.startsWith("/")) return <a {...props} href={layer.href} target="_blank" rel="noopener noreferrer" aria-label={accessible}>{content}</a>;
  return <Link {...props} href={layer.href} aria-label={accessible}>{content}</Link>;
}

export function ProductPage({ page }: { page: ProductPageData }) {
  // "Scroll direction" layers slide out while the visitor scrolls down and return on the way up.
  useEffect(() => {
    let last = window.scrollY;
    const onScroll = () => {
      const now = window.scrollY;
      if (now !== last) document.documentElement.dataset.scroll = now > last ? "down" : "up";
      last = now;
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => { window.removeEventListener("scroll", onScroll); delete document.documentElement.dataset.scroll; };
  }, []);

  return (
    <main className="min-h-dvh" style={{ background: page.background }}>
      <h1 className="sr-only">{page.title}</h1>
      <ScaledCanvas width={ARTBOARD} height={page.height}>
        <div className="relative" style={{ width: ARTBOARD, height: page.height }}>
          {page.layers.map((layer, index) => <LayerView key={index} layer={layer} />)}
        </div>
      </ScaledCanvas>
    </main>
  );
}
